(function(){'use strict';
const KEY='nawaf-hq-v5';
let currentTaskId='';
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason:'task-deleted'}}));window.dispatchEvent(new CustomEvent('nawaf:activity-updated'))}
function removeTaskFromState(state,id){if(!state||typeof state!=='object')state={};const task=(state.tasks||[]).find(t=>String(t.id)===String(id));state.tasks=Array.isArray(state.tasks)?state.tasks.filter(t=>String(t.id)!==String(id)):[];state.reports=Array.isArray(state.reports)?state.reports.filter(r=>String(r.sourceTaskId||'')!==String(id)):[];state.approvals=Array.isArray(state.approvals)?state.approvals.filter(a=>String(a.taskId||a.sourceTaskId||'')!==String(id)):[];if(Array.isArray(state.secretarySeen))state.secretarySeen=state.secretarySeen.filter(x=>!String(x).startsWith(String(id)+':'));
 if(task&&Array.isArray(state.employees)){const e=state.employees.find(x=>x.id===task.employeeId);if(e&&(e.task===task.title||['WORKING','RESEARCHING','REVIEWING','BLOCKED_BY_TOOL','WAITING_FOR_NAWAF'].includes(e.status))){e.task='';e.status='READY';e.updatedAt=new Date().toISOString()}}
 state.updatedAt=new Date().toISOString();return state}
async function persistDelete(id){let remote=null,updatedAt=null;try{const g=await fetch('/api/state',{cache:'no-store'}),j=await g.json();if(g.ok&&j?.ok){remote=j.state&&typeof j.state==='object'?j.state:{};updatedAt=j.updatedAt||null}}catch{}
 if(remote){removeTaskFromState(remote,id);for(let attempt=0;attempt<2;attempt++){const r=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:remote,baseUpdatedAt:updatedAt})});const j=await r.json().catch(()=>({}));if(r.ok&&j?.ok)return true;if(r.status===409&&j?.state){remote=removeTaskFromState(j.state,id);updatedAt=j.updatedAt||null;continue}break}}
 return window.HQCloud?.flush?await window.HQCloud.flush():false}
async function deleteTask(id){const s=read(),task=(s.tasks||[]).find(t=>String(t.id)===String(id));if(!task)return;if(!confirm(`حذف المهمة نهائيًا؟\n\n${task.title||'المهمة'}`))return;removeTaskFromState(s,id);write(s);document.querySelector('#v8-modal')?.classList.remove('show');try{await persistDelete(id)}catch{}window.NawafHQV8?.render?.();showToast('تم حذف المهمة')}
function showToast(text){let el=document.querySelector('.v8-toast');if(!el){el=document.createElement('div');el.className='v8-toast';document.body.appendChild(el)}el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
function inject(){const modal=document.querySelector('#v8-modal.show'),actions=modal?.querySelector('.v8-modal-actions');if(!modal||!actions||!currentTaskId||actions.querySelector('[data-delete-task]'))return;const b=document.createElement('button');b.type='button';b.className='v8-btn';b.dataset.deleteTask=currentTaskId;b.textContent='🗑 حذف المهمة';b.style.borderColor='rgba(255,95,95,.35)';b.style.color='#ff9d9d';actions.prepend(b)}
document.addEventListener('click',e=>{const row=e.target.closest('[data-task]');if(row){currentTaskId=row.dataset.task||'';setTimeout(inject,0);return}const del=e.target.closest('[data-delete-task]');if(del){e.preventDefault();e.stopPropagation();deleteTask(del.dataset.deleteTask)}} ,true);
const obs=new MutationObserver(()=>setTimeout(inject,0));function boot(){obs.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class']})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
window.NawafTaskDelete={deleteTask};
})();
